"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  Heart, 
  AlertOctagon, 
  Trash2,
  Lock,
  AlertTriangle,
  User,
  MessageSquare,
  CalendarMinus,
  RefreshCcw
} from "lucide-react";

// --- 1. MOCK DATA & CONFIGURATION ---
const HOLIDAYS = [{ date: "2026-01-26", name: "Republic Day" }];

// Existing Requests (The History Layer)
const EXISTING_REQUESTS = [
  { date: "2026-01-05", status: "approved", label: "Sick" },   // Green
  { date: "2026-01-06", status: "approved", label: "Sick" },
  { date: "2026-01-15", status: "pending", label: "Casual" },  // Yellow
  { date: "2026-01-29", status: "blackout", label: "Audit" },  // Gray/Lock
  { date: "2026-01-30", status: "blackout", label: "Audit" },
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, accrual: 1.5, color: "text-blue-600", bg: "bg-blue-50", requiresDoc: false },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, accrual: 1.0, color: "text-rose-600", bg: "bg-rose-50", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, accrual: 0.5, color: "text-amber-600", bg: "bg-amber-50", requiresDoc: false },
  { id: "comp", label: "Comp Off", icon: Umbrella, balance: 3, accrual: 0, color: "text-emerald-600", bg: "bg-emerald-50", requiresDoc: false },
  { id: "mat", label: "Maternity", icon: Baby, balance: 90, accrual: 0, color: "text-purple-600", bg: "bg-purple-50", requiresDoc: true },
  { id: "ber", label: "Bereave", icon: Heart, balance: 5, accrual: 0, color: "text-slate-600", bg: "bg-slate-100", requiresDoc: false },
  { id: "lop", label: "L.O.P", icon: AlertOctagon, balance: 0, accrual: 0, color: "text-red-600", bg: "bg-red-50", requiresDoc: false },
];

const COLLEAGUES = [
  { id: 1, name: "Mike Ross", role: "Backend Dev" },
  { id: 2, name: "Jessica Pearson", role: "Product Lead" },
  { id: 3, name: "Harvey Specter", role: "Legal/Compliance" },
];

export default function UltimateAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  
  const [typeId, setTypeId] = useState("annual");
  const [coverId, setCoverId] = useState(""); // Delegation
  const [reason, setReason] = useState("");
  const [file, setFile] = useState<File | null>(null);
  
  // Automation Toggles
  const [autoDecline, setAutoDecline] = useState(true);
  const [slackStatus, setSlackStatus] = useState(true);

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Close dropdown logic
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // --- LOGIC ENGINE ---
  const handleDateClick = (dateStr: string) => {
    // Prevent clicking blackout/existing dates
    const isBlocked = EXISTING_REQUESTS.some(req => req.date === dateStr);
    if (isBlocked) return;

    if (mode === "multi") {
      setMultiDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr].sort());
    } else if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
    } else {
      if (!range.start || (range.start && range.end)) setRange({ start: dateStr, end: "" });
      else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  // --- INTELLIGENCE STATS ---
  const stats = useMemo(() => {
    let days = 0, deduction = 0, sandwichWarning = false;
    let projection = 0; // Future accrual

    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = HOLIDAYS.some(h => h.date === dStr);
      const isWeekend = dObj.getDay() === 0 || dObj.getDay() === 6;
      const isBlocked = EXISTING_REQUESTS.some(r => r.date === dStr);
      
      if (!isHoliday && !isWeekend && !isBlocked) return 1;
      return 0;
    };

    // Calculate Deduction
    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (range.start && range.end) {
        let cur = new Date(range.start);
        let end = new Date(range.end);
        
        // Sandwich Rule Check: If Start is Friday (5) and End is Monday (1)
        if (cur.getDay() === 5 && end.getDay() === 1) sandwichWarning = true;

        while (cur <= end) {
          deduction += checkDay(cur.toISOString().split('T')[0]);
          days++;
          cur.setDate(cur.getDate() + 1);
        }
      }
    }

    // Accrual Forecasting (Mock logic: +Accrual Rate per month from now)
    const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;
    if (range.start) {
       const startMonth = new Date(range.start).getMonth();
       const currentMonth = new Date().getMonth(); // Jan = 0
       const monthDiff = startMonth - currentMonth;
       if (monthDiff > 0) projection = Number((monthDiff * selectedType.accrual).toFixed(1));
    }

    return { days, deduction, sandwichWarning, projection };
  }, [range, multiDates, mode, typeId]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;
  const hasValidDates = useMemo(() => {
    if (mode === "multi") return multiDates.length > 0;
    return !!(range.start && range.end);
  }, [mode, range, multiDates]);

  // Validation: Doc required? Cover required (>3 days)?
  const isCoverRequired = stats.deduction > 3;
  const isFormValid = hasValidDates && (!selectedType.requiresDoc || !!file) && (!isCoverRequired || !!coverId);

  return (
    <div className="flex h-screen w-full bg-[#F8FAFC] dark:bg-[#0B0F19] font-sans text-slate-800 dark:text-slate-200 overflow-hidden transition-colors duration-200">
      
      {/* --- LEFT: CALENDAR AREA (Flexible) --- */}
      <div className="flex-1 flex flex-col p-3 gap-3 h-full min-w-0">
        
        {/* Header */}
        <div className="flex items-center justify-between shrink-0 bg-white dark:bg-slate-900 px-4 py-2 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm h-14">
           <div className="flex items-center gap-2.5">
              <div className="bg-slate-900 dark:bg-white p-1.5 rounded-lg text-white dark:text-black"><CalendarIcon className="h-4 w-4" /></div>
              <div>
                <h1 className="text-sm font-bold text-slate-900 dark:text-white leading-tight">Absence<span className="text-slate-400">.ai</span></h1>
                <p className="text-[10px] text-slate-500 dark:text-slate-400 leading-tight">Elite Edition</p>
              </div>
           </div>
           
           <div className="flex bg-slate-100 dark:bg-slate-800 p-0.5 rounded-lg border border-slate-200 dark:border-slate-700">
              {['single', 'range', 'multi'].map((m) => (
                <button 
                  key={m}
                  onClick={() => { setMode(m as any); setRange({start:"", end:""}); setMultiDates([]); }}
                  className={`px-3 py-1 rounded-md text-[10px] font-bold capitalize transition-all ${
                    mode === m 
                    ? "bg-white dark:bg-slate-700 shadow text-slate-900 dark:text-white" 
                    : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"
                  }`}
                >
                  {m}
                </button>
              ))}
           </div>
        </div>

        {/* Calendar Canvas */}
        <div className="flex-1 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden relative">
           
           <div className="flex items-center justify-between px-5 py-3 border-b border-slate-100 dark:border-slate-800 shrink-0 h-12">
              <h2 className="text-sm font-bold text-slate-800 dark:text-white">January 2026</h2>
              {(range.start || multiDates.length > 0) && (
                <button 
                  onClick={() => { setMultiDates([]); setRange({start:"", end:""}); }}
                  className="flex items-center gap-1 text-[10px] font-bold text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 px-2 py-1 rounded transition-colors"
                >
                  <Trash2 className="h-3 w-3" /> Clear
                </button>
              )}
           </div>

           <div className="flex-1 p-4 overflow-y-auto">
              <div className="grid grid-cols-7 gap-1 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-bold text-slate-400 dark:text-slate-600 uppercase mb-1">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;

                    // CHECK EXISTING STATUS
                    const existing = EXISTING_REQUESTS.find(r => r.date === dateStr);

                    let isSelected = false, inRange = false;
                    if (mode === "multi") isSelected = multiDates.includes(dateStr);
                    else {
                        isSelected = range.start === dateStr || range.end === dateStr;
                        inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;
                    }

                    // --- INTELLIGENT STYLING LAYER ---
                    let btnClass = "border border-slate-50 dark:border-slate-800/50 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 hover:border-blue-300 dark:hover:border-blue-700";
                    let label = null;

                    if (existing) {
                        if (existing.status === 'approved') {
                            btnClass = "bg-emerald-50 dark:bg-emerald-900/20 border-emerald-100 dark:border-emerald-800 text-emerald-700 dark:text-emerald-400 opacity-60 cursor-not-allowed";
                            label = <span className="text-emerald-600 dark:text-emerald-400">✓ {existing.label}</span>;
                        } else if (existing.status === 'pending') {
                            btnClass = "bg-amber-50 dark:bg-amber-900/20 border-amber-100 dark:border-amber-800 text-amber-700 dark:text-amber-400 opacity-80 cursor-not-allowed";
                            label = <span className="text-amber-600 dark:text-amber-400">⧖ {existing.label}</span>;
                        } else if (existing.status === 'blackout') {
                            btnClass = "bg-slate-100 dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-400 cursor-not-allowed";
                            label = <span className="flex items-center gap-1"><Lock className="h-2 w-2"/> Blocked</span>;
                        }
                    } else if (isSelected) {
                        btnClass = "bg-slate-900 dark:bg-blue-600 border-slate-900 dark:border-blue-600 text-white shadow-md z-10 scale-[1.02]";
                    } else if (inRange) {
                        btnClass = "bg-blue-50 dark:bg-blue-900/20 border-blue-100 dark:border-blue-800 text-blue-600 dark:text-blue-200";
                    } else if (holiday) {
                        btnClass = "bg-rose-50 dark:bg-rose-900/10 border-rose-100 dark:border-rose-900/30 text-rose-600 dark:text-rose-400";
                        label = holiday.name;
                    } else if (isWeekend) {
                        btnClass = "bg-slate-50 dark:bg-slate-800/40 text-slate-400 dark:text-slate-600";
                    }

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         disabled={!!existing}
                         className={`relative h-full max-h-24 min-h-[3rem] rounded-lg text-left p-1.5 transition-all group ${btnClass}`}
                       >
                          <span className="text-xs font-bold leading-none">{day}</span>
                          {label && (
                            <span className={`absolute bottom-1 left-1 right-1 text-[8px] font-bold px-1 rounded truncate ${isSelected ? 'bg-white/20 text-white' : 'bg-white/50 dark:bg-black/20'}`}>
                                {typeof label === 'string' ? label : label}
                            </span>
                          )}
                          {isSelected && <span className="absolute top-1 right-1"><CheckCircle2 className="h-3 w-3" /></span>}
                       </button>
                    )
                 })}
              </div>
           </div>
           
           {/* Visual Legend */}
           <div className="px-5 py-2 border-t border-slate-100 dark:border-slate-800 flex gap-4 text-[9px] font-bold uppercase tracking-wider text-slate-400">
               <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-slate-900 dark:bg-blue-600"></div>Selected</div>
               <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-emerald-500"></div>Approved</div>
               <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-amber-500"></div>Pending</div>
               <div className="flex items-center gap-1.5"><div className="w-2 h-2 rounded-full bg-slate-300"></div>Blocked</div>
           </div>
        </div>
      </div>

      {/* --- RIGHT: INTELLIGENT SIDEBAR (Fixed 340px) --- */}
      <div className="w-[340px] flex-none p-3 pl-0 flex flex-col gap-3 h-full">
         
         {/* 1. SMART FORM */}
         <div className="flex-1 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden min-h-0">
            
            {/* Dynamic Header */}
            <div className="p-4 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30 shrink-0 space-y-4">
               
               {/* TYPE SELECTOR */}
               <div className="relative" ref={dropdownRef}>
                  <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block">Leave Type</label>
                  <button 
                    onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                    className="w-full flex items-center justify-between bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg p-2.5 hover:border-blue-400 transition-colors"
                  >
                     <div className="flex items-center gap-2 overflow-hidden">
                        <div className={`p-1 rounded ${selectedType.bg} ${selectedType.color} shrink-0`}><selectedType.icon className="h-3 w-3" /></div>
                        <span className="text-xs font-bold text-slate-900 dark:text-white truncate">{selectedType.label}</span>
                     </div>
                     <span className="text-[9px] font-bold bg-slate-100 dark:bg-slate-800 px-1.5 py-0.5 rounded text-slate-500 shrink-0">{selectedType.balance} Left</span>
                  </button>

                  {isDropdownOpen && (
                     <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg shadow-xl z-50 max-h-[250px] overflow-y-auto p-1 custom-scrollbar">
                        {LEAVE_TYPES.map(t => (
                           <button
                             key={t.id}
                             onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }}
                             className="w-full flex items-center justify-between p-2 hover:bg-slate-50 dark:hover:bg-slate-800 rounded group"
                           >
                              <div className="flex items-center gap-2 truncate">
                                 <div className={`p-1 rounded ${t.bg} ${t.color}`}><t.icon className="h-3 w-3" /></div>
                                 <span className="text-xs font-bold text-slate-700 dark:text-slate-300 group-hover:text-slate-900 dark:group-hover:text-white">{t.label}</span>
                              </div>
                              <span className="text-[9px] font-bold text-slate-400">{t.balance}</span>
                           </button>
                        ))}
                     </div>
                  )}
               </div>

               {/* ACCRUAL INTELLIGENCE */}
               {stats.projection > 0 && (
                 <div className="flex items-center gap-2 text-[10px] bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-300 p-2 rounded-lg border border-blue-100 dark:border-blue-800/50">
                    <RefreshCcw className="h-3 w-3" />
                    <span>You will accrue <strong>+{stats.projection} days</strong> by this date.</span>
                 </div>
               )}

               {/* SANDWICH RULE WARNING */}
               {stats.sandwichWarning && (
                 <div className="flex items-start gap-2 text-[10px] bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-300 p-2 rounded-lg border border-amber-100 dark:border-amber-800/50 animate-in fade-in">
                    <AlertTriangle className="h-3 w-3 shrink-0 mt-0.5" />
                    <span><strong>Policy Alert:</strong> Weekends bridged by leave may be deducted based on company policy.</span>
                 </div>
               )}

               {/* STATS ROW */}
               <div className="flex justify-between bg-slate-100 dark:bg-slate-800/50 p-3 rounded-lg items-center">
                  <div className="text-center w-1/2 border-r border-slate-200 dark:border-slate-700 pr-2">
                     <p className="text-[9px] font-bold text-slate-400 uppercase">Selected</p>
                     <p className="text-sm font-black text-slate-900 dark:text-white">{stats.days} Days</p>
                  </div>
                  <div className="text-center w-1/2 pl-2">
                     <p className="text-[9px] font-bold text-slate-400 uppercase">Net Deduction</p>
                     <p className="text-sm font-black text-rose-500">-{stats.deduction} Days</p>
                  </div>
               </div>
            </div>

            {/* Scrollable Inputs */}
            <div className="flex-1 p-4 space-y-4 overflow-y-auto custom-scrollbar min-h-0">
               
               {/* DELEGATION (Business Continuity) */}
               {isCoverRequired && (
                  <div className="animate-in slide-in-from-right-2">
                    <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block flex justify-between">
                       Delegate Work <span className="text-rose-500">* Required</span>
                    </label>
                    <div className="relative">
                       <select 
                         value={coverId} 
                         onChange={(e) => setCoverId(e.target.value)}
                         className="w-full appearance-none bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 rounded-lg p-2 text-xs font-medium focus:ring-1 focus:ring-blue-500 outline-none"
                       >
                          <option value="">Select a colleague...</option>
                          {COLLEAGUES.map(c => <option key={c.id} value={c.id}>{c.name} ({c.role})</option>)}
                       </select>
                       <User className="absolute right-3 top-2.5 h-3.5 w-3.5 text-slate-400 pointer-events-none" />
                    </div>
                  </div>
               )}

               {/* REASON */}
               <div>
                  <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block">Reason</label>
                  <textarea 
                     className="w-full h-16 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-950 p-2 text-xs font-medium focus:ring-1 focus:ring-blue-500 outline-none resize-none"
                     placeholder="Project status, handoff notes..."
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                  />
               </div>

               {/* ATTACHMENT */}
               {selectedType.requiresDoc && (
                  <div className="animate-in zoom-in-95">
                     <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block flex justify-between">
                        <span>Proof</span> <span className="text-rose-500 dark:text-rose-400">* Required</span>
                     </label>
                     <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`border-2 border-dashed rounded-lg h-10 flex items-center justify-center cursor-pointer transition-colors gap-2 ${file ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20" : "border-slate-200 dark:border-slate-700 hover:border-blue-400"}`}
                     >
                        <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                        {file ? (
                           <span className="text-[10px] font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1"><CheckCircle2 className="h-3 w-3"/> {file.name.slice(0, 15)}...</span>
                        ) : (
                           <div className="flex items-center gap-1 text-slate-400">
                             <UploadCloud className="h-3 w-3" />
                             <span className="text-[9px] font-bold">Upload File</span>
                           </div>
                        )}
                     </div>
                  </div>
               )}

               {/* AUTOMATION TOGGLES */}
               <div className="bg-slate-50 dark:bg-slate-800/40 p-3 rounded-lg space-y-2">
                  <label className="flex items-center justify-between cursor-pointer">
                     <div className="flex items-center gap-2 text-[10px] font-bold text-slate-600 dark:text-slate-300">
                        <MessageSquare className="h-3 w-3" /> Update Slack Status
                     </div>
                     <input type="checkbox" checked={slackStatus} onChange={() => setSlackStatus(!slackStatus)} className="accent-blue-600 h-3 w-3"/>
                  </label>
                  <label className="flex items-center justify-between cursor-pointer">
                     <div className="flex items-center gap-2 text-[10px] font-bold text-slate-600 dark:text-slate-300">
                        <CalendarMinus className="h-3 w-3" /> Auto-decline Meetings
                     </div>
                     <input type="checkbox" checked={autoDecline} onChange={() => setAutoDecline(!autoDecline)} className="accent-blue-600 h-3 w-3"/>
                  </label>
               </div>
            </div>
            
            {/* Submit */}
            <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/30 shrink-0">
               <button 
                  disabled={!isFormValid}
                  className={`w-full py-3 rounded-xl font-bold text-xs shadow-sm transition-all flex items-center justify-center gap-2 ${
                    isFormValid 
                    ? "bg-slate-900 dark:bg-blue-600 text-white hover:bg-black dark:hover:bg-blue-500 hover:shadow-md" 
                    : "bg-slate-200 dark:bg-slate-800 text-slate-400 dark:text-slate-600 cursor-not-allowed"
                  }`}
               >
                  {isFormValid ? "Confirm & Submit" : "Complete Requirements"}
               </button>
            </div>
         </div>
      </div>
    </div>
  );
}